/**
 * Nagilai service worker.
 *
 * Deliberately hand-written rather than generated by a plugin, because the
 * caching rules here are a privacy decision as much as a performance one.
 *
 * What is cached:
 *   - the app shell and immutable build assets (`/_next/static`, icons,
 *     fonts) — cache-first, they are content-hashed
 *   - a small offline page
 *   - book media (illustrations and narration audio) that the signed-in
 *     parent has actually opened — so a book already read once can be read
 *     again on a plane or in a car
 *
 * What is NEVER cached:
 *   - any non-GET request
 *   - anything under /api, /auth or /admin
 *   - the HTML of an authenticated page
 *
 * That last rule matters: this is a product about children, and Nagilai is
 * installed on shared family devices. A cached /library document would
 * survive a sign-out and be readable by the next person to open the app.
 * Media is cached instead, and `CLEAR_PRIVATE_CACHES` wipes it the moment
 * the session ends (see src/components/site/pwa.tsx).
 */

const VERSION = 'v1';
const SHELL_CACHE = `nagilai-shell-${VERSION}`;
const ASSET_CACHE = `nagilai-assets-${VERSION}`;
const MEDIA_CACHE = `nagilai-media-${VERSION}`;

const OFFLINE_URL = '/offline';
const SHELL_URLS = [OFFLINE_URL, '/icons/icon-192.png', '/icons/icon-512.png', '/manifest.webmanifest'];

/** Caches that must be cleared when a session ends. */
const PRIVATE_CACHES = [MEDIA_CACHE];

/** Route prefixes the worker must never intercept. */
const BYPASS_PREFIXES = ['/api/', '/auth/', '/admin'];

/**
 * Route prefixes whose HTML must never be stored.
 *
 * The private areas, plus the auth screens: a cached sign-in page can
 * outlive the session it belonged to, and serving one from cache after a
 * redirect is confusing at best.
 */
const PRIVATE_PAGE_PREFIXES = [
  '/library',
  '/create',
  '/children',
  '/settings',
  '/admin',
  '/share',
  '/login',
  '/signup',
  '/forgot-password',
];

const MEDIA_CACHE_LIMIT = 160;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // `reload` skips the HTTP cache so a stale shell is never installed.
      .then((cache) => cache.addAll(SHELL_URLS.map((url) => new Request(url, { cache: 'reload' }))))
      .catch(() => undefined)
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith('nagilai-') && !key.endsWith(VERSION))
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;

  if (type === 'SKIP_WAITING') {
    self.skipWaiting();
    return;
  }

  if (type === 'CLEAR_PRIVATE_CACHES') {
    event.waitUntil(Promise.all(PRIVATE_CACHES.map((name) => caches.delete(name))));
  }
});

self.addEventListener('fetch', (event) => {
  const request = event.request;

  // Never touch mutations: a cached POST would be a lost story.
  if (request.method !== 'GET') return;

  let url;
  try {
    url = new URL(request.url);
  } catch {
    return;
  }

  if (url.protocol !== 'http:' && url.protocol !== 'https:') return;

  const sameOrigin = url.origin === self.location.origin;

  if (sameOrigin && BYPASS_PREFIXES.some((prefix) => url.pathname.startsWith(prefix))) return;

  // Immutable build output and icons.
  if (
    sameOrigin &&
    (url.pathname.startsWith('/_next/static/') ||
      url.pathname.startsWith('/icons/') ||
      url.pathname === '/favicon.ico')
  ) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  // Google Fonts stylesheets and font files.
  if (url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com') {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  // Book media from Supabase Storage. Signed URLs expire, so this is
  // cache-first keyed on the whole URL: the exact URL a parent already
  // loaded keeps working offline, and a fresh signed URL fetches fresh.
  if (!sameOrigin && isStorageObject(url)) {
    event.respondWith(cacheFirst(request, MEDIA_CACHE, MEDIA_CACHE_LIMIT));
    return;
  }

  if (request.mode === 'navigate') {
    event.respondWith(handleNavigation(request, url));
  }
});

function isStorageObject(url) {
  return url.pathname.includes('/storage/v1/object/');
}

async function cacheFirst(request, cacheName, limit) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  try {
    const response = await fetch(request);
    if (response && response.ok) {
      await cache.put(request, response.clone());
      if (limit) void trimCache(cacheName, limit);
    }
    return response;
  } catch (error) {
    const fallback = await cache.match(request);
    if (fallback) return fallback;
    throw error;
  }
}

/**
 * Network-first for pages, so a signed-in parent always sees live data.
 * Only public pages are stored; a private page falls back to the offline
 * screen rather than to a stale copy of somebody's library.
 */
async function handleNavigation(request, url) {
  const isPrivate = PRIVATE_PAGE_PREFIXES.some((prefix) => url.pathname.startsWith(prefix));

  try {
    const response = await fetch(request);

    if (!isPrivate && response && response.ok && response.type === 'basic') {
      const cache = await caches.open(SHELL_CACHE);
      await cache.put(request, response.clone());
    }
    return response;
  } catch (error) {
    if (!isPrivate) {
      const cached = await caches.match(request);
      if (cached) return cached;
    }

    const offline = await caches.match(OFFLINE_URL);
    if (offline) return offline;
    throw error;
  }
}

/** Keeps the media cache bounded, evicting the oldest entries first. */
async function trimCache(cacheName, limit) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length <= limit) return;

  for (const key of keys.slice(0, keys.length - limit)) {
    await cache.delete(key);
  }
}
